return (static function (): array {
    $reference = 'https://docs.arduino.cc/hardware/uno-rev3/';
    $bank = require __DIR__.'/arduino_questions.php';
    $serialSketch = static fn (string $message): string => 'void setup() {'."\n  Serial.begin(9600);\n  Serial.println(\"".$message."\");\n}\n\nvoid loop() {}\n";
    $topics = [
        'robotics' => [
            'title' => 'Introduction to Robotics',
            'goal' => 'Identify a robot’s sensors, controller and actuators, then explain a sense-decide-act feedback loop using a classroom example.',
            'concept' => 'A robot combines a physical system with programmed decisions. Sensors gather information, the controller applies rules, and actuators affect the surroundings. A feedback loop measures again after acting. Automation can follow fixed rules without machine learning; a moving machine is not automatically intelligent. Draw arrows showing how a distance sensor could influence an indicator or a stopped motor.',
            'wiring' => 'Use only the Uno and a teacher-approved USB cable for the first demonstration. Identify possible sensors and actuators in the unpowered kit. No motor or moving mechanism is connected in this lesson.',
            'experiment' => 'List an input, decision and output for a classroom need. Trace three situations: a normal reading, an obstacle and a missing reading. Upload the worked serial sketch and compare the message with your planned system. Explain which parts are simulated by the message and which would need real hardware.',
            'code' => $serialSketch('Sense -> Decide -> Act -> Check again'),
            'output' => 'Serial Monitor at 9600 baud: Sense -> Decide -> Act -> Check again',
            'mistake' => 'Do not claim that an LED demonstration identifies people, learns by itself or certifies a robot as safe.',
            'assignment' => ['Robot system map', 'Design an input-process-output map for a desk obstacle reminder. Label a sensor, a decision rule, an actuator and a safe response to invalid data. Add an Arduino serial sketch that prints the planned sequence.', 'A labeled map and a Serial Monitor message describing the chosen sequence.'],
            'challenge' => ['Robot decision cards', 'Create three fictional sensor cases for the same robot. Write a sketch that prints an appropriate action for each case and explain why a missing reading must not be treated as a clear path.', 'Three labeled cases with justified actions, including a safe invalid-data case.'],
        ],
        'kit-safety' => [
            'title' => 'Beginner Kit Components and Safe Working',
            'goal' => 'Inventory a beginner kit, identify common components and apply a power-off inspection routine before every circuit change.',
            'concept' => 'Resistors limit current, LEDs emit light, switches provide input, sensors measure conditions and drivers control loads. Similar-looking modules can use different voltages or pin orders. For the classic Uno R3, use its published operating limits rather than an absolute damage limit as a design target. Begin with teacher-approved low-voltage USB experiments; never connect household mains to the kit.',
            'wiring' => 'Keep power disconnected while sorting parts. Check LED polarity, resistor values and module labels. Use a 220–330 ohm series resistor for an ordinary indicator LED unless your teacher specifies another suitable value. Motors and servos require a teacher-checked supply/driver plan; never power them from a GPIO pin. Stop immediately if anything becomes hot.',
            'experiment' => 'Make an inventory with each part’s name, purpose and known rating. Explain the difference between a signal pin and a power connection. In pairs, inspect an unpowered diagram for a missing resistor and a 5V-to-GND short. Correct the diagram, obtain a teacher check, then run the serial checklist.',
            'code' => $serialSketch('Power off -> Inspect -> Teacher check -> Power on'),
            'output' => 'Serial Monitor: Power off -> Inspect -> Teacher check -> Power on',
            'mistake' => 'A correct sketch cannot prevent damage caused by reversed power, a short circuit or an overloaded pin.',
            'assignment' => ['My kit inspection sheet', 'Create a labeled component inventory and a five-step inspection checklist. Write a serial sketch that prints the checklist in order. Identify a missing LED resistor and a short in a teacher-provided diagram.', 'An inventory, two corrected diagram faults and an ordered checklist message.'],
            'challenge' => ['Safety fault detective', 'Review three teacher-created, unpowered circuit scenarios. Identify the hazard, explain its cause and propose a safe repair. Print a different status message for each corrected scenario.', 'Three justified repairs; no unsafe circuit is energized.'],
        ],
        'breadboards' => [
            'title' => 'Breadboards, Circuits and LED Polarity',
            'goal' => 'Trace connected breadboard nodes and build a current-limited LED circuit with a complete return path.',
            'concept' => 'A breadboard connects groups of holes internally. The center channel separates opposing terminal groups; long supply rails may be split. A circuit needs a complete path, and two leads in the same node are electrically joined. A diagram describes connections, not just where parts look attractive. Check continuity only with power disconnected.',
            'wiring' => 'After teacher approval, connect D8 through a 220–330 ohm resistor to the LED anode; connect the LED cathode to GND. Put the resistor leads in different nodes. Verify your actual breadboard’s rail connections and the LED polarity before applying USB power.',
            'experiment' => 'Mark nodes on a paper breadboard. Trace the full D8-to-GND current path. Build with power off, obtain an inspection and run the example. If the LED is off, disconnect power and inspect one connection at a time. Record an open-circuit fault and its repair.',
            'code' => "void setup() {\n  pinMode(8, OUTPUT);\n  digitalWrite(8, HIGH);\n}\n\nvoid loop() {}\n",
            'output' => 'The correctly wired external LED on D8 stays on.',
            'mistake' => 'Placing both resistor leads or both LED leads in one connected strip bypasses the intended circuit.',
            'assignment' => ['Trace and light one LED', 'Draw and build the D8-resistor-LED-GND circuit. Mark connected nodes, explain the resistor and record the inspected wiring and observed state.', 'A steady LED, labeled current path and power-off inspection record.'],
            'challenge' => ['Find the open path', 'Use a teacher-approved unpowered fault diagram to locate two open connections. Repair the design, then modify the sketch to demonstrate ON and OFF states after inspection.', 'Two documented repairs and a repeatable ON/OFF demonstration.'],
        ],
        'uno-board' => [
            'title' => 'Meet the Arduino Uno R3 and Its Pins',
            'goal' => 'Locate power, digital, analog and PWM pins on an Uno R3 and distinguish the board from other Uno models.',
            'concept' => 'The classic Uno R3 uses an ATmega328P with digital pins D0–D13 and analog inputs A0–A5. Its logic operates at 5V. The tilde-marked digital pins support PWM. D0/RX and D1/TX are shared with serial communication, so beginners should leave them free while using Serial Monitor. Uno R4 uses a different processor; this course’s specific limits and examples target R3.',
            'wiring' => 'Use the official R3 pinout to label 5V, 3.3V, GND, RESET, A0 and D8. Leave AREF and supply pins unchanged. No external load is required for the worked sketch; LED_BUILTIN addresses the board’s controllable built-in LED.',
            'experiment' => 'Compare a photo of your actual board with its pinout. Identify a possible sensor input, LED output and common ground. Upload the example and press reset to observe the startup message again. Explain why a pin marked 5V is not interchangeable with any signal pin.',
            'code' => "void setup() {\n  Serial.begin(9600);\n  pinMode(LED_BUILTIN, OUTPUT);\n  digitalWrite(LED_BUILTIN, HIGH);\n  Serial.println(\"Uno R3 ready\");\n}\n\nvoid loop() {}\n",
            'output' => 'Built-in LED on; Serial Monitor at 9600 baud shows: Uno R3 ready',
            'mistake' => 'Do not assume R3, R4 and every compatible board have identical processors, voltages or pin capabilities.',
            'assignment' => ['My Uno pin map', 'Annotate an R3 pin map and propose safe pins for a button, external LED and analog sensor. Upload a startup message using LED_BUILTIN.', 'A checked pin map and repeatable startup indication after reset.'],
            'challenge' => ['Pin assignment planner', 'Plan an R3 prototype with three PWM color channels, an analog input and Serial Monitor. Choose nonconflicting pins and justify keeping D0/D1 available for serial use.', 'A labeled pin table with three valid PWM choices and no duplicated signal assignment.'],
        ],
        'ide-upload' => [
            'title' => 'Arduino IDE, Sketches and Serial Monitor',
            'goal' => 'Save, verify and upload a sketch to the selected Uno R3, then interpret labeled Serial Monitor output.',
            'concept' => 'A sketch is saved as an .ino file. The Arduino build system supplies the surrounding framework: setup runs once after startup and loop is repeatedly called. Verify builds for the selected board; Upload transfers the program. A successful build or upload does not prove that a circuit or algorithm meets its requirements.',
            'wiring' => 'Use a data-capable USB cable and the teacher-approved IDE installation. Select Arduino Uno and the correct connected port. If no port appears, check the cable and the board’s official driver guidance with your teacher rather than downloading an unknown driver.',
            'experiment' => 'Save a sketch in a folder with the same base name, verify it and read the first relevant error if building fails. Upload the example and open Serial Monitor at 9600 baud. Press reset and explain the difference between the startup message and messages from loop. Keep a saved known-working revision.',
            'code' => "void setup() {\n  Serial.begin(9600);\n  Serial.println(\"Setup runs once\");\n}\n\nvoid loop() {\n  Serial.println(\"Loop is running\");\n  delay(1000);\n}\n",
            'output' => 'After reset: Setup runs once, followed by Loop is running about once per second.',
            'mistake' => 'An unreadable Serial Monitor message may be a baud mismatch; a successful upload alone is not a completed test.',
            'assignment' => ['My first saved sketch', 'Create your own startup and repeated learning-goal messages. Save, verify and upload the sketch, recording the board, port, baud rate and observed output.', 'One startup line and repeated loop lines, with a saved .ino revision.'],
            'challenge' => ['Explain and repair an upload problem', 'Diagnose a teacher-provided scenario involving a wrong board, charge-only cable or baud mismatch. Repair the setup and demonstrate a counter message increasing once per second.', 'A documented diagnosis and serial lines 1, 2, 3 in order at about one-second intervals.'],
        ],
        'blink' => [
            'title' => 'Digital Output and LED Blink Patterns',
            'goal' => 'Use pinMode, digitalWrite and delay to create, predict and measure a repeatable LED pattern.',
            'concept' => 'OUTPUT makes a pin drive a signal. In an LED circuit from output through resistor to GND, HIGH normally turns the LED on and LOW turns it off. delay uses milliseconds and pauses normal loop work. A complete blink period includes both on-time and off-time. Frequency is the number of complete cycles each second.',
            'wiring' => 'First use LED_BUILTIN. For an external LED, disconnect power and connect D8 through a 220–330 ohm resistor to the anode, with the cathode to GND. Change the ledPin constant to 8 only after the circuit is inspected.',
            'experiment' => 'Predict the period for 250 ms HIGH and 750 ms LOW. Run at least ten cycles and compare the observation with your prediction. Change one delay at a time and record on-time, off-time, period and approximate frequency. Explain why timing changes do not remove the series resistor.',
            'code' => "const byte ledPin = LED_BUILTIN;\nvoid setup() { pinMode(ledPin, OUTPUT); }\n\nvoid loop() {\n  digitalWrite(ledPin, HIGH);\n  delay(250);\n  digitalWrite(ledPin, LOW);\n  delay(750);\n}\n",
            'output' => 'LED on for 250 ms and off for 750 ms: approximately one cycle per second.',
            'mistake' => 'Do not confuse a single delay with the full blink period or assume that long delays keep checking a button.',
            'assignment' => ['Two timing patterns', 'Create two documented LED patterns with different on/off timing. Predict and measure their complete periods; retain current limiting for an external LED.', 'A timing table and a repeatable demonstration of both patterns.'],
            'challenge' => ['Three short, one long', 'Create a repeating pattern of three 100 ms flashes and one 600 ms flash. Separate flashes with 200 ms off and repeat the whole pattern after a clearly documented pause.', 'Three short flashes followed by one long flash; the complete sequence and measured cycle are documented.'],
        ],
        'sketch-logic' => [
            'title' => 'Variables, Conditions and Reusable Sketch Logic',
            'goal' => 'Use meaningful constants, variables, arithmetic and functions to control a small Arduino behavior.',
            'concept' => 'A variable holds a value, while const communicates that a setting should stay fixed. Names can record meaning and units, such as blinkMs. C++ arithmetic and comparisons apply inside sketches. A reusable function groups a named operation. Test decisions at the boundary, not just with convenient examples.',
            'wiring' => 'Use only the built-in LED and USB. The pin stays LED_BUILTIN; change the timing value in software rather than moving wires while powered.',
            'experiment' => 'Trace the count variable over three loop passes. Explain the difference between = and ==. Predict which branch runs at counts 2, 3 and 4, then confirm the serial messages. Refactor the LED action into a function and compare behavior before and after.',
            'code' => "const byte ledPin = LED_BUILTIN;\nint count = 0;\nvoid flashOnce(unsigned long onMs) {\n  digitalWrite(ledPin, HIGH); delay(onMs);\n  digitalWrite(ledPin, LOW); delay(300);\n}\nvoid setup() { Serial.begin(9600); pinMode(ledPin, OUTPUT); }\nvoid loop() {\n  count++; Serial.println(count);\n  if (count <= 3) { flashOnce(100); }\n  else { flashOnce(500); count = 0; }\n}\n",
            'output' => 'Serial counts 1, 2, 3, 4; three short flashes precede one longer flash, then the count restarts.',
            'mistake' => 'Assigning a value with = is different from comparing values; use names and units to prevent timing mistakes.',
            'assignment' => ['Named pattern controller', 'Create named pin and timing constants plus a flash function. Use a counter to choose a short or long pattern and document its boundary values.', 'A readable sketch with a traced counter table and matching LED behavior.'],
            'challenge' => ['Parameter-controlled signaling', 'Write a function that flashes the built-in LED a requested number of times. Demonstrate calls for 1, 2 and 4 flashes and explain a safe response to an invalid request.', 'Three distinct tested patterns and a justified invalid-request rule.'],
        ],
        'buttons' => [
            'title' => 'Pushbuttons, Pull-ups and Debouncing',
            'goal' => 'Read an active-LOW button with INPUT_PULLUP and distinguish a button state from a single accepted press.',
            'concept' => 'An input needs a defined electrical level. INPUT_PULLUP makes an unpressed input HIGH when a switch connects it to GND on pressing. Real contacts may bounce, and counting the held state on every loop pass can register many presses. A stable-state debounce plus edge detection can recognize a single new press.',
            'wiring' => 'With power off, connect a button between D2 and GND. Check the internal pairing of its legs; legs on the same side may already be joined. Use LED_BUILTIN for output. Do not connect this switch to a pin configured as a HIGH output.',
            'experiment' => 'Predict readings for released and pressed states. Run the level-following worked example, then inspect repeated samples from a long hold. For the assignment, store the previous accepted state and require about 30 ms of stable input before counting a new press. Test taps, long holds and release.',
            'code' => "const byte buttonPin = 2;\nvoid setup() {\n  pinMode(buttonPin, INPUT_PULLUP);\n  pinMode(LED_BUILTIN, OUTPUT);\n  Serial.begin(9600);\n}\nvoid loop() {\n  bool pressed = digitalRead(buttonPin) == LOW;\n  digitalWrite(LED_BUILTIN, pressed ? HIGH : LOW);\n  Serial.println(pressed ? \"Pressed\" : \"Released\");\n  delay(50);\n}\n",
            'output' => 'Pressed: built-in LED on and Pressed printed. Released: LED off and Released printed. This example follows level; it is not a press counter.',
            'mistake' => 'A button held LOW is not a new press on every loop iteration. The level-following example is not a complete debounce algorithm.',
            'assignment' => ['One press, one count', 'Build the pull-up button circuit and write a debounced, edge-detected counter. A long hold must count once; another count requires release and a new press.', 'Ten deliberate presses produce ten accepted events; long holds do not add repeated counts.'],
            'challenge' => ['Debounced toggle light', 'Toggle an LED only on a new debounced press. Record quick taps, holds and deliberate release. Explain how state storage prevents repeated toggles.', 'Each accepted press changes the light once, including after a long hold.'],
        ],
        'traffic-lights' => [
            'title' => 'Traffic-light Sequences and State Tables',
            'goal' => 'Plan and implement a classroom traffic-light model using explicit output states and measured phase durations.',
            'concept' => 'A state table describes the outputs, duration and next state of a model. Deliberate transitions help prevent contradictory outputs. A classroom sequence is a learning prototype, not a certified road controller. First build a predictable timed cycle; later compare blocking delays with a responsive millis-based design.',
            'wiring' => 'Connect red, amber and green LEDs to D8, D9 and D10, each through its own 220–330 ohm resistor, with cathodes to GND. Inspect polarity and pin labels with power off.',
            'experiment' => 'Write a red-green-amber state table with durations 3 s, 3 s and 1 s. Set every output explicitly when entering a phase. Observe three cycles and calculate the approximately 7-second period. Discuss how a request button could be delayed by blocking code.',
            'code' => "const byte redPin=8, amberPin=9, greenPin=10;\nvoid phase(bool r, bool a, bool g, unsigned long waitMs) {\n  digitalWrite(redPin,r); digitalWrite(amberPin,a); digitalWrite(greenPin,g);\n  delay(waitMs);\n}\nvoid setup() { pinMode(redPin,OUTPUT); pinMode(amberPin,OUTPUT); pinMode(greenPin,OUTPUT); }\nvoid loop() { phase(HIGH,LOW,LOW,3000); phase(LOW,LOW,HIGH,3000); phase(LOW,HIGH,LOW,1000); }\n",
            'output' => 'Red 3 s -> green 3 s -> amber 1 s -> repeat; only the selected color is on.',
            'mistake' => 'Changing only the new LED without clearing previous outputs can leave unintended colors on together.',
            'assignment' => ['Documented three-light cycle', 'Implement the checked three-LED circuit and a complete state table. Measure the phases and demonstrate three correct repeated cycles.', 'A labeled state table and a repeatable red-green-amber sequence.'],
            'challenge' => ['Pedestrian request model', 'Add a pull-up button and a documented request rule. Insert an all-red transition where your model requires it. Explain the response delay and why this prototype must not control a real road.', 'A repeatable request sequence with no conflicting green states and a measured response time.'],
        ],
        'analog-input' => [
            'title' => 'Analog Input and Potentiometer Calibration',
            'goal' => 'Read a potentiometer with the Uno R3 ADC, estimate voltage and record a calibration table.',
            'concept' => 'A potentiometer forms an adjustable voltage divider. Its wiper provides a voltage between its end-terminal voltages. Uno R3 analogRead normally gives a 10-bit reading from 0 to 1023. Converting counts to volts requires an assumed or measured reference. Small changes in readings can reflect noise and component tolerances.',
            'wiring' => 'Connect the end terminals of a 10k potentiometer to 5V and GND; connect its identified wiper to A0. Check the actual part. Never connect an input beyond its permitted voltage range. Use USB power for this low-current experiment.',
            'experiment' => 'Record readings at the two ends, approximate quarter positions and the middle. Calculate volts using the example’s assumed 5V reference, labeling the result as an estimate. Compare repeated readings with the knob still. Predict the ADC value for approximately half the reference voltage.',
            'code' => "void setup() { Serial.begin(9600); }\nvoid loop() {\n  int raw = analogRead(A0);\n  float volts = raw * 5.0 / 1023.0;\n  Serial.print(\"ADC=\"); Serial.print(raw);\n  Serial.print(\" estimated V=\"); Serial.println(volts,2);\n  delay(250);\n}\n",
            'output' => 'ADC readings rise from near 0 toward 1023 across the knob travel; the estimated voltage ranges near 0–5 V.',
            'mistake' => 'A reading is an ADC count, not automatically a voltage or a calibrated physical measurement.',
            'assignment' => ['Five-position calibration', 'Record five knob positions, three readings at each and an estimated voltage. Write a sketch with clearly labeled ADC and voltage output, stating the reference assumption.', 'A five-position table and labeled serial output with units.'],
            'challenge' => ['Three-zone control input', 'Classify the knob into LOW, MIDDLE and HIGH zones using two documented thresholds. Test just below, at and above each boundary and record your chosen equality rules.', 'Three correctly labeled zones and six boundary checks.'],
        ],
        'pwm' => [
            'title' => 'PWM and LED Brightness Control',
            'goal' => 'Use an Uno R3 PWM pin and map an analog reading to a controlled LED brightness setting.',
            'concept' => 'PWM switches a pin between logic levels while changing the fraction of time HIGH. On Uno R3 this is not a general-purpose true analog-voltage output. analogWrite commonly takes 0–255 on PWM-capable pins. Perceived brightness also depends on the LED and vision; a duty value is not a calibrated brightness measurement.',
            'wiring' => 'Connect D5 through a 220–330 ohm resistor to an LED anode and the cathode to GND. Connect a checked potentiometer wiper to A0 with ends on 5V and GND. Inspect before powering.',
            'experiment' => 'Predict duty values for analog readings near 0, 512 and 1023. Run the worked example and record brightness observations at 0, about 128 and 255. Explain why the pin still switches between digital levels rather than producing a precise continuous intermediate voltage.',
            'code' => "const byte ledPin=5;\nvoid setup() { pinMode(ledPin,OUTPUT); }\nvoid loop() {\n  int raw=analogRead(A0);\n  int duty=constrain(raw/4,0,255);\n  analogWrite(ledPin,duty);\n  delay(10);\n}\n",
            'output' => 'Turning the potentiometer changes the external LED from off through intermediate brightness to on.',
            'mistake' => 'Do not confuse the 0–1023 ADC range with the 0–255 PWM setting or describe PWM as a precision DAC.',
            'assignment' => ['Knob-controlled brightness', 'Build and document the potentiometer-controlled LED. Show the ADC-to-duty calculation and test minimum, middle and maximum inputs.', 'A smooth usable control range and three recorded ADC/duty observations.'],
            'challenge' => ['Automatic fade with limits', 'Create an automatic fade that increases and decreases duty without going outside 0–255. Explain both turning points and keep the series resistor.', 'A repeatable fade in both directions with documented endpoint tests.'],
        ],
        'rgb' => [
            'title' => 'RGB LEDs and Additive Color Mixing',
            'goal' => 'Control three current-limited RGB channels and document how PWM combinations change emitted color.',
            'concept' => 'An RGB LED combines red, green and blue emitters. Mixing emitted light is additive: red plus green can appear yellow, and all three channels can approximate white. Common-cathode and common-anode versions need different wiring and drive interpretation. Channel efficiencies vary, so equal settings are not guaranteed to look equally bright.',
            'wiring' => 'This example requires a verified common-cathode RGB LED. Connect its common cathode to GND and its red, green and blue leads through separate 220–330 ohm resistors to D3, D5 and D6. Confirm the actual package pinout rather than guessing from lead length.',
            'experiment' => 'Test each channel independently before mixing. Record settings for red, green, blue, yellow, white and off. Compare prediction with observation and explain a different drive rule for a common-anode part. Do not change wiring while powered.',
            'code' => "const byte redPin=3, greenPin=5, bluePin=6;\nvoid color(byte r, byte g, byte b) { analogWrite(redPin,r); analogWrite(greenPin,g); analogWrite(bluePin,b); }\nvoid setup() { pinMode(redPin,OUTPUT); pinMode(greenPin,OUTPUT); pinMode(bluePin,OUTPUT); }\nvoid loop() { color(255,0,0); delay(1000); color(255,255,0); delay(1000); color(0,0,255); delay(1000); color(0,0,0); delay(1000); }\n",
            'output' => 'For the stated common-cathode wiring: red -> yellow -> blue -> off, about one second each.',
            'mistake' => 'One shared resistor does not independently limit all three channels; identify the common terminal and each channel correctly.',
            'assignment' => ['Six-color palette', 'Create and document six RGB states, including off. Use a color function and provide a table of requested channel settings and observed appearance.', 'A six-state palette with safe separate channel resistors.'],
            'challenge' => ['Status colors with meaning', 'Design a three-state classroom status indicator using clearly distinct colors. Define each meaning, allow an off state and test all transitions.', 'A documented state/color table and a repeatable demonstration.'],
        ],
        'light-sensor' => [
            'title' => 'LDR Light Sensing and a Night-light',
            'goal' => 'Calibrate an LDR divider and implement a night-light decision with tested lighting boundaries.',
            'concept' => 'A typical LDR becomes less resistive in brighter light. A divider converts that changing resistance into a measurable voltage. With the LDR above the junction and a 10k resistor below it, brighter light generally raises the junction reading. Raw counts are not lux without a calibration model. Separate on/off thresholds can reduce rapid switching near a boundary.',
            'wiring' => 'Connect 5V -> LDR -> A0 junction -> 10k resistor -> GND. Connect an external LED through its own 220–330 ohm resistor from D8 to GND. Inspect the divider orientation and LED polarity with power off.',
            'experiment' => 'Measure bright, dim and covered conditions without heating or wetting the sensor. Choose a threshold from your measurements. Observe whether the LED illuminates the LDR itself and changes the reading. For an extension, use distinct switch-on and switch-off thresholds.',
            'code' => "void setup() { pinMode(8,OUTPUT); Serial.begin(9600); }\nvoid loop() {\n  int lightValue=analogRead(A0);\n  bool dark=lightValue<400;\n  digitalWrite(8,dark?HIGH:LOW);\n  Serial.print(lightValue); Serial.println(dark?\" DARK: light ON\":\" BRIGHT: light OFF\");\n  delay(200);\n}\n",
            'output' => 'With this divider and threshold: 120 -> DARK, LED ON; 850 -> BRIGHT, LED OFF. Actual classroom readings must be calibrated.',
            'mistake' => 'Reversing the divider reverses the relationship; do not copy a threshold or claim lux accuracy without checking.',
            'assignment' => ['Calibrated classroom night-light', 'Record readings in three lighting conditions, choose and justify a threshold, then demonstrate a correctly labeled night-light response.', 'A calibration table and matching bright/dark behavior.'],
            'challenge' => ['Stable night-light', 'Add separate ON and OFF thresholds based on measurements. Test near both boundaries and explain how hysteresis reduces rapid LED switching.', 'A state diagram and observations showing stable boundary behavior.'],
        ],
        'buzzer' => [
            'title' => 'Passive Piezo Buzzers and Sound Alerts',
            'goal' => 'Create brief, meaningful sound patterns and distinguish frequency, duration and buzzer type.',
            'concept' => 'A passive piezo needs a changing electrical signal to produce a tone; an active buzzer may contain its own oscillator. Identify the actual part and its current requirements. tone takes a frequency in hertz and can take a duration in milliseconds. Longer or louder sound is not automatically more informative. Agree on short comfortable tests with the class.',
            'wiring' => 'Use a teacher-checked low-current passive piezo suitable for this signal circuit on D8 and GND, with any protective series resistor required by its specification. A higher-current sound module needs an appropriate driver; do not substitute one directly. Check timer interactions before combining tone with PWM projects.',
            'experiment' => 'Predict how frequency and duration change the sound. Run the short worked pattern, then create two named alerts with different purposes. Stop if the sound is uncomfortable. Explain what noTone does and record the timing rather than claiming a loudness measurement.',
            'code' => "const byte soundPin=8;\nvoid setup() { pinMode(soundPin,OUTPUT); }\nvoid loop() { tone(soundPin,1000,150); delay(250); tone(soundPin,1500,150); delay(250); noTone(soundPin); delay(2000); }\n",
            'output' => 'Two brief tones of different pitch, then a quiet pause; the pattern repeats.',
            'mistake' => 'Do not assume an active sound module and a passive piezo have identical drive requirements or connect an unknown siren to GPIO.',
            'assignment' => ['Two meaningful alerts', 'Create a short attention pattern and a different confirmation pattern. Document frequencies, durations, quiet gaps and the identified buzzer type.', 'Two recognizable brief patterns and a correct timing table.'],
            'challenge' => ['Threshold sound reminder', 'Use a calibrated potentiometer threshold to select an alert. Add a quiet state and a rule preventing continuous repeated beeping while the condition remains unchanged.', 'One alert on a new accepted condition, followed by quiet until reset or clearance.'],
        ],
        'servo' => [
            'title' => 'Positional Servo Motors and Safe Movement',
            'goal' => 'Command a hobby positional servo within checked mechanical limits and explain its power and signal requirements.',
            'concept' => 'A positional hobby servo receives a target command while its internal controller drives toward a position. Its real angle depends on the device and calibration. A continuous-rotation servo behaves differently. Mechanical stalls can draw substantial current, so test with the horn free and modest travel before attaching a mechanism.',
            'wiring' => 'Use a teacher-approved positional servo, signal on D9 and a suitable regulated external servo supply. Join its signal ground to Uno GND. Do not power a servo from GPIO or casually join an external positive rail to the Uno 5V rail while USB is connected. Verify polarity and current ratings before power-on.',
            'experiment' => 'Check the servo’s safe range. With the horn unobstructed, request 20, 90 and 160 degrees only if those positions are supported. Compare requested and observed positions, stop at any strain and explain why a power sag can reset the board. Do not force the horn by hand.',
            'code' => "#include <Servo.h>\nServo arm;\nvoid setup() { arm.attach(9); arm.write(90); delay(1000); }\nvoid loop() { arm.write(20); delay(1000); arm.write(90); delay(1000); arm.write(160); delay(1000); }\n",
            'output' => 'A checked positional servo moves to three modest targets and pauses at each. Actual angles require measurement.',
            'mistake' => 'A servo signal pin is not its power supply; repeated resets or stalling require stopping and reviewing power and mechanics.',
            'assignment' => ['Three-position servo study', 'Document the servo type, supply plan and safe movement limits. Demonstrate three supported targets and record requested versus observed behavior.', 'A checked power diagram and three repeatable unobstructed positions.'],
            'challenge' => ['Knob-controlled safe arm', 'Map a potentiometer to a teacher-approved limited servo range, such as 30–150 degrees. Constrain the command and test both ends and the middle with no attached load.', 'Limited, predictable positioning and a table showing input-to-angle mapping.'],
        ],
        'ultrasonic' => [
            'title' => 'Ultrasonic Distance Measurement',
            'goal' => 'Measure an HC-SR04 echo with a timeout, estimate distance and handle invalid readings explicitly.',
            'concept' => 'An ultrasonic module measures a sound pulse’s round-trip time. Using an approximate sound speed of 0.0343 cm per microsecond, distance is duration times speed divided by two. Temperature, target angle and material affect results. A timeout is not proof that the path is clear; it means the expected echo did not arrive in the allowed interval.',
            'wiring' => 'For a verified 5V HC-SR04 on an Uno R3, connect VCC to 5V, GND to GND, TRIG to D7 and ECHO to D8. Confirm the module’s pin labels. Other controller voltages may require level shifting. Use a fixed ruler reference and a clear test area.',
            'experiment' => 'Compare readings with a ruler at several classroom distances, including 10, 20 and 40 cm where the module supports them. Test an angled or absent target. Record invalid readings separately rather than inventing a distance. Leave about 100 ms between measurements.',
            'code' => "const byte triggerPin=7, echoPin=8;\nvoid setup() { pinMode(triggerPin,OUTPUT); pinMode(echoPin,INPUT); Serial.begin(9600); }\nvoid loop() {\n  digitalWrite(triggerPin,LOW); delayMicroseconds(2);\n  digitalWrite(triggerPin,HIGH); delayMicroseconds(10); digitalWrite(triggerPin,LOW);\n  unsigned long duration=pulseIn(echoPin,HIGH,30000UL);\n  if(duration==0) { Serial.println(\"INVALID: no echo\"); }\n  else { Serial.print(duration*0.0343/2.0); Serial.println(\" cm\"); }\n  delay(100);\n}\n",
            'output' => 'Valid echoes produce a labeled approximate distance; a missing echo prints INVALID: no echo.',
            'mistake' => 'Do not treat a zero pulse duration as a valid zero-centimeter or clear-path measurement.',
            'assignment' => ['Distance evidence table', 'Measure at least three known distances, compare estimated and ruler values and record one invalid case. Include units, the timeout and possible measurement limitations.', 'Three comparison rows, an explicit invalid row and a checked sketch.'],
            'challenge' => ['Safe proximity indicator', 'Create FAR, NEAR and INVALID output states using a documented distance threshold. Test below, at and above the boundary, plus no echo. Invalid input must select the planned safe state.', 'A four-case test log with no fabricated distance on timeout.'],
        ],
        'temperature' => [
            'title' => 'TMP36 Temperature Sensing and Calibration',
            'goal' => 'Identify a temperature sensor, convert a TMP36 reading with stated assumptions and compare it with a classroom reference.',
            'concept' => 'This worked example is specifically for a TMP36 analog temperature sensor, not an LM35, thermistor or digital humidity module. Its approximate model is 0.5V at 0 degrees Celsius with 0.01V per degree. Convert ADC counts to estimated volts first, then apply the sensor’s model. Quantization, reference voltage and sensor tolerances limit accuracy.',
            'wiring' => 'Optional kit component: a verified TMP36. Use its manufacturer’s package diagram to identify supply, output and ground. Connect output to A0 with a compatible supply and common GND. If the kit contains a different temperature sensor, the teacher must change both wiring and conversion before using this lesson.',
            'experiment' => 'Use room-temperature comparisons only; do not use flames, hot liquids or an unsafe heat source. Compare with a suitable classroom thermometer and report conditions. Trace the conversion for 0.75V and 0.80V even if hardware is unavailable. Do not claim medical or safety-device accuracy.',
            'code' => "void setup() { Serial.begin(9600); }\nvoid loop() {\n  int raw=analogRead(A0);\n  float volts=raw*5.0/1023.0;\n  float temperatureC=(volts-0.5)*100.0;\n  Serial.print(\"Estimated temperature: \"); Serial.print(temperatureC,1); Serial.println(\" C\");\n  delay(1000);\n}\n",
            'output' => 'For the stated TMP36 model, 0.75V corresponds to approximately 25 C; the actual displayed reading depends on the sensor and reference.',
            'mistake' => 'Do not substitute an LM35 or thermistor while retaining the TMP36 offset and scale.',
            'assignment' => ['Temperature conversion record', 'Identify the sensor model and document its conversion. Record classroom readings with units and compare with a reference; if no TMP36 is available, label the supplied-voltage exercise as simulated data.', 'A model-specific wiring/conversion record and clearly labeled observed or simulated data.'],
            'challenge' => ['Calibrated temperature reminder', 'Create NORMAL, ABOVE THRESHOLD and invalid/unreasonable-value states for a teacher-approved model. State the reference assumption and test supplied values near the threshold.', 'A justified boundary test table and a clear statement that this is not a medical or certified fire device.'],
        ],
        'lcd' => [
            'title' => '16x2 LCD Messages and Sensor Displays',
            'goal' => 'Wire a parallel 16x2 LCD, display labeled information on both rows and update a value without leaving stale characters.',
            'concept' => 'A 16x2 character display has sixteen character columns and two rows. Cursor coordinates are zero-based in LiquidCrystal. Contrast is separate from the text data. A parallel display and one with an I2C backpack need different wiring and initialization. Updating a shorter value may leave old characters, so clear the affected area or pad the new value deliberately.',
            'wiring' => 'This example uses a teacher-checked parallel HD44780-compatible LCD, not an I2C backpack. Map RS=D12, E=D11, LCD D4=D5, D5=D4, D6=D3 and D7=D2. Connect RW to GND, supply and ground per the module specification, and a contrast potentiometer to VO. Check backlight current limiting. Arduino library: LiquidCrystal.',
            'experiment' => 'Start with fixed messages on both rows before adding a sensor. Confirm contrast and wiring if the screen is blank. Then replace a four-character value with a shorter one and explain any leftover characters. Update only when needed to avoid distracting flicker.',
            'code' => "#include <LiquidCrystal.h>\nLiquidCrystal lcd(12,11,5,4,3,2);\nvoid setup() {\n  lcd.begin(16,2);\n  lcd.setCursor(0,0); lcd.print(\"Grade 9 Robotics\");\n  lcd.setCursor(0,1); lcd.print(\"Ready to learn\");\n}\nvoid loop() {}\n",
            'output' => 'Row 1: Grade 9 Robotics; row 2: Ready to learn, within the 16-column display.',
            'mistake' => 'Do not copy parallel wiring into an I2C-backpack display or assume lcd.print clears the entire old value.',
            'assignment' => ['Two-row learning display', 'Display your project name and a changing fictional measurement with units. Document the interface, pin mapping, contrast connection and stale-character handling.', 'Readable text on both rows, with shorter updates leaving no old digits.'],
            'challenge' => ['Readable sensor dashboard', 'Show a live potentiometer value and a status label. Limit update frequency and reserve fixed character positions. Test minimum, maximum and transitions between values of different lengths.', 'A stable two-row display with documented position and update rules.'],
        ],
        'keypad' => [
            'title' => 'Matrix Keypads and Menu Input',
            'goal' => 'Explain row-column scanning and map a single pressed matrix key to a meaningful menu character.',
            'concept' => 'A 4x4 keypad joins a row and column when a key is pressed. Scan one row LOW at a time and read pulled-up columns. This introductory sketch leaves unselected rows as high-impedance inputs to avoid conflicting driven outputs. It is intended for one key at a time; multi-key ambiguity and ghosting need a more complete design.',
            'wiring' => 'Identify the actual keypad connector mapping before wiring. For this example use rows D2–D5 and columns D6–D9. Columns use INPUT_PULLUP; a selected row briefly becomes an OUTPUT driven LOW and is then restored to INPUT. No external Keypad library is required for this single-key demonstration.',
            'experiment' => 'Trace the row/column lookup on paper, then test each key independently. Hold a key and observe repeated reports; explain why an accepted-event menu needs debounce and release detection. Use only fictional menu values, never real security or payment PINs.',
            'code' => "const byte rows[4]={2,3,4,5}, cols[4]={6,7,8,9};\nconst char keys[4][4]={{'1','2','3','A'},{'4','5','6','B'},{'7','8','9','C'},{'*','0','#','D'}};\nvoid setup() {\n  Serial.begin(9600);\n  for(byte i=0;i<4;i++) { pinMode(rows[i],INPUT); digitalWrite(rows[i],LOW); pinMode(cols[i],INPUT_PULLUP); }\n}\nvoid loop() {\n  for(byte r=0;r<4;r++) {\n    pinMode(rows[r],OUTPUT); digitalWrite(rows[r],LOW); delayMicroseconds(10);\n    for(byte c=0;c<4;c++) { if(digitalRead(cols[c])==LOW) { Serial.println(keys[r][c]); } }\n    pinMode(rows[r],INPUT);\n  }\n  delay(100);\n}\n",
            'output' => 'One pressed key at a time prints its mapped character; a held key repeats in this demonstration.',
            'mistake' => 'This basic scanner is not a secure lock or a complete multi-key/debounced input system.',
            'assignment' => ['Sixteen-key mapping record', 'Document the actual row/column wiring and test all sixteen key positions individually. Report any mismatch and explain why a held key repeats in the worked example.', 'A complete key-map test table with observed characters.'],
            'challenge' => ['Single-press menu selector', 'Add stable-state debounce and release detection to select one of three fictional menu modes. A held key must not repeatedly change the mode.', 'Three named modes and repeatable one-press behavior, with no real PIN data.'],
        ],
        'joystick' => [
            'title' => 'Joystick Axes, Calibration and Dead Zones',
            'goal' => 'Read two analog joystick axes and a digital button, then classify direction using measured center dead zones.',
            'concept' => 'A typical kit joystick has two potentiometers and a press switch. Resting values are usually near the ADC midpoint but are not guaranteed to equal exactly 512. A dead zone ignores small center variation. Orientation can reverse the apparent direction of an axis, so measure and document your own mounting before controlling a mechanism.',
            'wiring' => 'Check the joystick’s labels. For a compatible 5V module, connect VRx to A0, VRy to A1, switch to D2 using INPUT_PULLUP, VCC to the specified supply and GND to common ground. Begin with serial output only and no moving mechanism.',
            'experiment' => 'Record released center and both extremes of each axis. Choose a center dead zone from repeated data. Display LEFT, CENTER or RIGHT for X and label Y separately. Test the center switch and explain why output commands would need constraining before connecting a servo or motor.',
            'code' => "void setup() { Serial.begin(9600); pinMode(2,INPUT_PULLUP); }\nvoid loop() {\n  int x=analogRead(A0), y=analogRead(A1);\n  Serial.print(\"X=\"); Serial.print(x); Serial.print(\" Y=\"); Serial.print(y);\n  Serial.print(\" \");\n  if(x<450) { Serial.print(\"LEFT\"); } else if(x>570) { Serial.print(\"RIGHT\"); } else { Serial.print(\"CENTER\"); }\n  Serial.println(digitalRead(2)==LOW?\" BUTTON\":\" RELEASED\"); delay(100);\n}\n",
            'output' => 'Labeled X/Y readings, a calibrated X direction and button state; the example’s 450–570 dead zone must be checked on the actual module.',
            'mistake' => 'Do not require an exact resting value or assume every mounting gives the same direction signs.',
            'assignment' => ['Joystick calibration sheet', 'Record center and extreme X/Y values, select dead zones and display both axis directions plus the button state. Keep the test free of moving machinery.', 'A calibration table and stable centered direction output.'],
            'challenge' => ['Five-state direction interface', 'Choose CENTER, UP, DOWN, LEFT or RIGHT from both axes using a documented diagonal-priority rule. Test every state and explain how noise is handled.', 'Five predictable states and a complete state/test table.'],
        ],
        'pir' => [
            'title' => 'PIR Motion Events and Responsible Sensing',
            'goal' => 'Interpret a PIR module’s digital events while explaining warm-up, retriggering, environmental and privacy limitations.',
            'concept' => 'PIR sensing responds to changing infrared patterns across sensing zones. It does not identify a person or reliably count exact occupancy. Many modules need a settling period after startup and offer timing/retrigger settings. A stationary person may no longer produce a change; changing heat or movement outside the intended area can also affect results.',
            'wiring' => 'Use a teacher-checked PIR module whose supply and output are compatible with Uno R3. Connect its signal to D2 and its ground to common GND. Confirm its actual pinout and warm-up guidance. The output indicator is LED_BUILTIN; do not connect security equipment or actuators.',
            'experiment' => 'Mark the module’s settling period and keep its output labeled WARMING UP. Then observe motion across and toward the field, stillness and the module’s hold time. Discuss why these events cannot prove who attended class and why the model must not publish identity claims.',
            'code' => "const byte motionPin=2;\nvoid setup() {\n  Serial.begin(9600); pinMode(motionPin,INPUT); pinMode(LED_BUILTIN,OUTPUT);\n  Serial.println(\"WARMING UP: check your module settling time\"); delay(60000);\n}\nvoid loop() {\n  bool event=digitalRead(motionPin)==HIGH;\n  digitalWrite(LED_BUILTIN,event?HIGH:LOW);\n  Serial.println(event?\"Motion event\":\"No current event\"); delay(200);\n}\n",
            'output' => 'After the demonstrated 60-second settling wait, motion-like events light the indicator; actual warm-up and output timing depend on the module.',
            'mistake' => 'A PIR event is not face recognition, identity verification or a guaranteed exact occupancy count.',
            'assignment' => ['PIR event observations', 'Record settling, movement, stillness and hold-time observations. Identify the module settings and state clearly that the output represents events rather than identity.', 'A labeled event log and honest limitations statement.'],
            'challenge' => ['Quiet event indicator', 'Create a non-alarming indicator that logs only output-state changes after warm-up. Test how repeated motion and a long module HIGH state affect your event logic.', 'A change-based log without claiming to count unique people.'],
        ],
        'motor-driver' => [
            'title' => 'DC Motors, Drivers and Controlled Speed',
            'goal' => 'Explain why a DC motor needs a rated driver and supply, then demonstrate controlled start and stop under supervision.',
            'concept' => 'A GPIO supplies a control signal, not general motor power. A suitable H-bridge can set direction while a PWM enable input changes the average drive. Real speed depends on the load and supply; duty is not a direct RPM measurement. Stall current, flyback protection, driver heating and mechanical guarding must be considered before a live test.',
            'wiring' => 'Optional supervised hardware: a teacher-checked L293D-style driver/module and a small motor within its ratings. Example signals are enable D5, IN1 D7 and IN2 D8. Use the driver’s documented logic and motor supplies, suitable flyback protection and common signal ground. Check supply jumpers and prevent backfeeding into USB/Uno rails. Keep the shaft/wheel free and clear.',
            'experiment' => 'Begin with a paper driver/supply diagram or LED model if the kit lacks a suitable driver. For an approved live test, command stop before a modest forward duty setting, then stop again. Record supply, load and observations. Reversing or loading a motor requires a new teacher check, not a random software change.',
            'code' => "const byte enablePin=5, in1=7, in2=8;\nvoid stopMotor() { analogWrite(enablePin,0); digitalWrite(in1,LOW); digitalWrite(in2,LOW); }\nvoid setup() { pinMode(enablePin,OUTPUT); pinMode(in1,OUTPUT); pinMode(in2,OUTPUT); stopMotor(); }\nvoid loop() {\n  stopMotor(); delay(2000);\n  digitalWrite(in1,HIGH); digitalWrite(in2,LOW); analogWrite(enablePin,100); delay(2000);\n  stopMotor(); delay(3000);\n}\n",
            'output' => 'For the checked driver: stop, modest forward drive for about 2 seconds, then stop. A paper/LED alternative must be labeled as a model.',
            'mistake' => 'Never attach a motor directly to an I/O pin or assume adding a driver makes every supply, load and reversal safe.',
            'assignment' => ['Motor control and supply plan', 'Produce a checked driver diagram with ratings and a stop-first sequence. Demonstrate only with teacher-approved hardware, or provide a clearly labeled paper/LED simulation.', 'A justified power/driver plan and observed or modeled stop/forward/stop behavior.'],
            'challenge' => ['Controlled direction study', 'After explicit teacher hardware approval, plan a forward-stop-reverse-stop sequence with a stop interval before reversal. Use a paper model if a safe driver or mechanism is unavailable.', 'A state table, ratings check and a documented safe sequence; no claim of precise speed without measurement.'],
        ],
        'millis' => [
            'title' => 'Nonblocking Timing with millis and States',
            'goal' => 'Schedule LED actions using unsigned elapsed-time arithmetic while keeping a button responsive.',
            'concept' => 'A long delay stops normal loop work from checking other inputs. millis returns an unsigned elapsed-millisecond count. Comparing now minus previous with an interval supports ordinary short-interval scheduling across unsigned rollover. Keeping the loop responsive still requires checking all other calls: a long sensor read or serial operation can block too.',
            'wiring' => 'Use LED_BUILTIN plus a button between D2 and GND configured INPUT_PULLUP. Inspect the switch legs with power off. No motor or servo is connected during the timing-response measurement.',
            'experiment' => 'Compare a one-second delay blink with the worked scheduler. Press the button during each part of the cycle and measure the difference in response. Explain why exact timestamp equality is fragile. For two scheduled tasks, keep separate timestamps and document whether the schedule prioritizes minimum delay or fixed cadence.',
            'code' => "const byte buttonPin=2;\nunsigned long previous=0;\nbool ledOn=false;\nvoid setup() { pinMode(LED_BUILTIN,OUTPUT); pinMode(buttonPin,INPUT_PULLUP); }\nvoid loop() {\n  unsigned long now=millis();\n  if(now-previous>=500UL) { previous=now; ledOn=!ledOn; }\n  if(digitalRead(buttonPin)==LOW) { digitalWrite(LED_BUILTIN,LOW); }\n  else { digitalWrite(LED_BUILTIN,ledOn?HIGH:LOW); }\n}\n",
            'output' => 'LED toggles on a roughly 500 ms schedule; a pressed button overrides it off without waiting for a long delay.',
            'mistake' => 'Replacing one delay does not make every library or sensor call nonblocking. Do not require now to equal one exact millisecond.',
            'assignment' => ['Responsive scheduled light', 'Implement the scheduler and button override. Record response during at least three phases and explain the unsigned subtraction check.', 'A working override and a timing comparison against a blocking version.'],
            'challenge' => ['Two independent schedules', 'Schedule two LED indicators at different intervals and retain a checked button input. Use independent timestamps, state your timing policy and test simultaneous due actions.', 'Two visible schedules plus a responsive button, supported by a timing log.'],
        ],
        'robot-functions' => [
            'title' => 'Robot Decision Functions, Testing and Debugging',
            'goal' => 'Separate sensing, validation, decisions and outputs into testable functions and use evidence to diagnose a fault.',
            'concept' => 'Small functions clarify the role of each operation. A decision can be tested using supplied values before a mechanism is connected. Use clear units and a distinct invalid reading. Log inputs, selected states and outputs, avoiding private data. A failed test is evidence for a revision; keep earlier working tests to catch regressions.',
            'wiring' => 'The worked decision example uses supplied distances and Serial Monitor only, so no sensor or mechanism is needed. Connect real sensors later only after validating their wiring and timeout handling. Keep all moving outputs disconnected during paper/serial logic tests.',
            'experiment' => 'Trace the decision for 10, 15, 20 and -1 cm. Explain the equality boundary and invalid sentinel. Introduce a teacher-provided comparison error, record the failed test, repair one cause and rerun every case. Name the functions by their purpose rather than using anonymous labels.',
            'code' => "const char* decideAction(float distanceCm) {\n  if(distanceCm<0) { return \"INVALID: safe stop\"; }\n  if(distanceCm<15) { return \"NEAR: stop\"; }\n  return \"FAR: ready\";\n}\nvoid setup() {\n  Serial.begin(9600);\n  float cases[]={10,15,20,-1};\n  for(byte i=0;i<4;i++) { Serial.print(cases[i]); Serial.print(\" cm -> \"); Serial.println(decideAction(cases[i])); }\n}\nvoid loop() {}\n",
            'output' => '10 -> NEAR: stop; 15 and 20 -> FAR: ready; -1 -> INVALID: safe stop.',
            'mistake' => 'Do not hide an invalid measurement inside an ordinary valid value or change several suspected causes before retesting.',
            'assignment' => ['Boundary-tested decision functions', 'Write separate validation and decision functions for a proximity reminder. Supply normal, equality-boundary and invalid test values before connecting hardware.', 'A saved sketch and expected/actual table covering every branch.'],
            'challenge' => ['Debug and prove the repair', 'Repair a teacher-provided threshold or units bug. Keep a failing-before and passing-after record, then rerun the earlier cases to demonstrate no regression.', 'A reasoned repair with repeatable before/after test evidence.'],
        ],
        'capstone' => [
            'title' => 'Grade 9 Capstone: Smart Classroom Proximity Reminder',
            'goal' => 'Design, build and explain a supervised sensor-driven prototype using documented success criteria, safe states and repeated tests.',
            'concept' => 'A complete prototype joins a defined need, checked circuit, readable sketch, observations and reflection. The worked design uses a distance sensor and built-in indicator rather than moving machinery. The teacher can extend it with a checked display or actuator, but extra parts do not replace evidence. Classroom success does not certify a device for collision prevention, security or emergency use.',
            'wiring' => 'Use the checked HC-SR04 circuit from the distance lesson: TRIG D7, ECHO D8, compatible 5V and GND; output uses LED_BUILTIN. Optional modules require their own revised pin, power and library plan. Rotate wiring, coding, testing and reporting roles; each learner explains an individual contribution.',
            'experiment' => 'Agree on behavior below 15 cm, at the threshold, farther away and on timeout. Build and test in stages. Record at least eight runs covering normal, boundary, invalid and repeated-use conditions. Save a revision before each deliberate improvement. Demonstrate the circuit and explain a limitation, a failed test and a change supported by evidence.',
            'code' => "const byte trigPin=7, echoPin=8;\nfloat readDistanceCm() {\n  digitalWrite(trigPin,LOW); delayMicroseconds(2); digitalWrite(trigPin,HIGH); delayMicroseconds(10); digitalWrite(trigPin,LOW);\n  unsigned long us=pulseIn(echoPin,HIGH,30000UL);\n  return us==0?-1.0:us*0.0343/2.0;\n}\nvoid setup() { Serial.begin(9600); pinMode(trigPin,OUTPUT); pinMode(echoPin,INPUT); pinMode(LED_BUILTIN,OUTPUT); }\nvoid loop() {\n  float cm=readDistanceCm();\n  bool valid=cm>=0; bool warn=!valid||cm<15.0;\n  digitalWrite(LED_BUILTIN,warn?HIGH:LOW);\n  if(!valid) { Serial.println(\"INVALID: check sensor\"); }\n  else { Serial.print(cm); Serial.println(warn?\" cm: NEAR\":\" cm: FAR\"); }\n  delay(100);\n}\n",
            'output' => 'NEAR below 15 cm and INVALID both light the warning indicator; valid readings at or above 15 cm show FAR and turn it off.',
            'mistake' => 'A copied finished sketch or high XP alone does not demonstrate practical understanding. Keep individual explanations and test evidence.',
            'assignment' => ['Documented proximity reminder', 'Create a problem statement, circuit/power plan, sketch, eight-run test log and individual reflection for the supervised proximity reminder. Justify the invalid-input safe state.', 'A complete review portfolio with normal, boundary, invalid and repeated-use evidence.'],
            'challenge' => ['Evidence-led capstone improvement', 'Choose one observed weakness, such as threshold chatter or unclear status messages. Propose a measurable improvement, save a new revision and compare at least four before/after cases without weakening the safe state.', 'A justified improvement, comparative test results and an individual explanation of remaining limitations.'],
        ],
    ];

    $lessons = $activities = $articles = $practice = [];
    $starter = "void setup() {\n  Serial.begin(9600);\n  // Configure the checked input and output pins here.\n}\n\nvoid loop() {\n  // Implement your own solution and test each required case.\n}\n";
    foreach ($topics as $slug => $topic) {
        $number = count($lessons) + 1;
        $key = 'arduino-'.$slug;
        $term = $number <= 9 ? 'Term1' : ($number <= 17 ? 'Term2' : 'Term3');
        $questions = [];
        foreach (explode("\n", trim($bank[$slug])) as $index => $row) {
            [$prompt, $answer, $first, $second, $third] = array_pad(explode(' | ', trim($row)), 5, null);
            $options = $index < 5 ? [$first, $second] : [$first, $second, $third];
            $correct = crc32($prompt) % (count($options) + 1);
            array_splice($options, $correct, 0, [$answer]);
            $questions[] = ['prompt' => $prompt, 'options' => $options, 'correct' => $correct,
                'why' => 'Correct: '.$answer.'. '.$topic['goal']];
        }
        $lesson = [
            'title' => 'Arduino Uno · '.$topic['title'], 'topic' => $topic['title'], 'objective' => $topic['goal'],
            'course' => 'arduino-uno', 'grade_level' => 'Grade 9', 'term' => $term, 'practice' => $key,
            'minutes' => 18, 'icon' => 'memory', 'version' => 1, 'reference_url' => $reference,
            'subtopics' => ['Concepts and vocabulary', 'Components, pin mapping and safe wiring', 'Sketch tracing and practical evidence'],
            'sections' => [
                ['title' => 'Understand the system', 'text' => $topic['concept']],
                ['title' => 'Parts, wiring and inspection', 'text' => $topic['wiring']],
                ['title' => 'Predict, build, test and explain', 'text' => $topic['experiment']],
            ],
            'code' => $topic['code'], 'output' => $topic['output'], 'mistake' => $topic['mistake'],
            'checks' => array_slice($questions, 0, 5),
        ];
        $lesson['ilaw'] = [
            'title' => $lesson['title'], 'learning_area' => 'Grade 9 Robotics · Arduino Uno R3',
            'grade_section' => 'Grade 9 · teacher enters the target section', 'sessions' => $slug === 'capstone' ? 4 : 2,
            'references' => $reference."\nhttps://docs.arduino.cc/learn/\nhttps://docs.wokwi.com/parts/wokwi-arduino-uno\nTeacher checks the exact component datasheets and applicable school curriculum.",
            'ai_declaration' => 'AI-assisted draft prepared with OpenAI Codex. The teacher must verify the factual content, hardware, local curriculum alignment, timing and assessment decisions before use.',
            'competency' => $topic['goal'].' Teacher maps this suggested outcome to the school’s adopted Grade 9 ICT/TLE/robotics competency; no official competency code is asserted.',
            'intentions' => "By the end, learners can:\n1. ".$topic['goal']."\n2. Explain the stated wiring and one relevant limitation.\n3. Produce the assignment evidence and justify a revision using a test result.",
            'learner_context' => 'Learners have basic C++ sequencing experience. Check readiness with an input-process-output or code-tracing prompt. Pair learners when kits are shared, rotate roles and require an individual explanation. Offer printed pin maps and supplied-data tasks where hardware is unavailable.',
            'pre_lesson' => 'Session 1, 10 min: ask learners to predict '.$topic['output'].' Discuss why a prediction is not yet evidence. Identify parts with power off and review: '.$topic['mistake'],
            'learning_experience' => "Session 1 (suggested 50 min): readiness and safety check 10 min; model concepts and trace the worked sketch 15 min; paired diagram/wiring inspection and guided trial 20 min; exit explanation 5 min.\nSession 2 (suggested 50 min): recall 5 min; independent/pair assignment with rotating roles 25 min; compare test evidence 10 min; checkpoints and reflection 10 min. Adjust for actual class periods.\nConcept focus: ".$topic['concept']."\nPractical sequence: ".$topic['experiment'].($slug === 'capstone' ? "\nAdditional sessions 3–4: staged build, peer testing, individual demonstration and evidence-led revision." : ''),
            'resources' => $topic['wiring']."\nUno R3/data cable, teacher-approved Arduino IDE and required Arduino libraries where named. CodeQuest saves sketches and reviews; hardware behavior is checked on a suitable simulator or inspected low-voltage hardware. Offline alternative: printed circuit/code tracing and clearly labeled supplied observations.",
            'integration' => 'Connect science measurement, mathematical units and computing decisions to a classroom need. Encourage accessible text explanations of visual or audible outputs; grade reasoning and evidence rather than kit ownership or decorative complexity.',
            'assessing_learning' => "During modeling, ask learners to explain one input-to-output decision. Inspect the unpowered wiring before power-on.\nFive checkpoints:\n".implode("\n", array_map(static fn (array $check, int $i): string => ($i + 1).'. '.$check['prompt'].' Answer: '.$check['options'][$check['correct']], $lesson['checks'], array_keys($lesson['checks'])))."\nUse the separate 10-question quiz after review. Practical evidence: ".$topic['assignment'][2].' Rubric: correctness, logic, readability/documentation and explanation, 0–4 each. Final scores remain a teacher decision; XP is not an official grade.',
            'ways_forward' => 'Record observed misconceptions after the lesson rather than inventing completed reflections. Reteach using one supplied example and one corrected circuit/trace. Learners revise their own evidence. Enrichment: '.$topic['challenge'][1].' Review the next lesson’s prerequisites and adjust pace using checkpoint and practical results.',
        ];
        $lessons[$key] = $lesson;
        $activities[$key] = ['term' => $term, 'difficulty' => $number <= 9 ? 'Easy' : ($number <= 17 ? 'Mid' : 'Hard'), 'questions' => array_slice($questions, 5, 10)];
        foreach (['assignment', 'challenge'] as $kind) {
            [$title, $requirement, $evidence] = $topic[$kind];
            $activities[$key][$kind] = [
                'title' => 'Arduino · '.$title, 'unit' => 'Arduino UNO R3',
                'objective' => $requirement."\nHardware/inspection: ".$topic['wiring']."\nSubmit your own sketch in Code Lab and explain the circuit, test cases, observations and one limitation. Test hardware only after the teacher checks it; this activity is not a console-output auto-test.",
                'sample_input' => '', 'sample_output' => $evidence, 'starter_code' => $starter,
                'test_cases' => [], 'hints' => ['Trace the worked lesson example, then design your own solution.', 'Label every signal pin and power connection before building.', 'Record expected and observed behavior, including a boundary or invalid case.'],
            ];
        }
        $articles[$key] = [
            'title' => 'Robotics notebook · '.$topic['title'], 'category' => 'Projects',
            'introduction' => 'This Grade 9 robotics discussion asks you to connect '.$topic['title'].' with evidence rather than copying a finished project. Read the example and explain the design in your own words.',
            'prompts' => ['Explain how the input, decision and output relate in this lesson. Use one specific example.', 'Predict one normal result and one boundary or invalid result. State how you would test your prediction.', 'Discuss this limitation or common mistake: '.$topic['mistake'].' Explain one improvement you would make.'],
            'teacher_notes' => 'Look for understanding of: '.$topic['goal'].' Expected evidence: '.$topic['assignment'][2].' Ask a follow-up about a boundary or invalid case. Review individual reasoning and distinguish observed results from supplied/simulated data. Do not give mastery credit for a copied image alone.',
        ];
        $practice[$key] = ['title' => 'Arduino practice · '.$topic['title'], 'objective' => $activities[$key]['assignment']['objective'],
            'sample_output' => $topic['assignment'][2], 'hint' => implode(' ', $activities[$key]['assignment']['hints']), 'code' => $starter, 'environment' => 'arduino-uno'];
    }

    return ['title' => 'Arduino Uno Robotics', 'reference_url' => $reference, 'lessons' => $lessons, 'activities' => $activities, 'articles' => $articles, 'practice' => $practice];
})();
